int __mnt_is_readonly(struct vfsmount *mnt) /* <=== __mnt_is_readonly */ 
{
	if (mnt->mnt_flags & MNT_READONLY)
		return 1;
	if (mnt->mnt_sb->s_flags & MS_RDONLY)
		return 1;
	return 0;
}

bool ns_capable(struct user_namespace *ns, int cap) /* <=== ns_capable */ 
{
	if (unlikely(!cap_valid(cap))) {
		pr_crit("capable() called with invalid cap=%u\n", cap);
		BUG();
	}

	if (security_capable(current_cred(), ns, cap) == 0) {
		current->flags |= PF_SUPERPRIV;
		return true;
	}
	return false;
}

static inline int security_capable(const struct cred *cred, /* <=== security_capable */ 
				   struct user_namespace *ns, int cap)
{
	return cap_capable(cred, ns, cap, SECURITY_CAP_AUDIT);
}

static inline struct mount *real_mount(struct vfsmount *mnt) /* <=== real_mount */ 
{
	return container_of(mnt, struct mount, mnt);
}

static inline void namespace_lock(void) /* <=== namespace_lock */ 
{
	down_write(&namespace_sem);
}

static void namespace_unlock(void) /* <=== namespace_unlock */ 
{
	struct mount *mnt;
	struct hlist_head head = unmounted;

	if (likely(hlist_empty(&head))) {
		up_write(&namespace_sem);
		return;
	}

	head.first->pprev = &head.first;
	INIT_HLIST_HEAD(&unmounted);

	up_write(&namespace_sem);

	synchronize_rcu();

	while (!hlist_empty(&head)) {
		mnt = hlist_entry(head.first, struct mount, mnt_hash);
		hlist_del_init(&mnt->mnt_hash);
		if (mnt->mnt_ex_mountpoint.mnt)
			path_put(&mnt->mnt_ex_mountpoint);
		mntput(&mnt->mnt);
	}
}

